:root {
  --ink: #163d52;
  --water: #dff4f4;
  --blue: #267aa5;
  --coral: #ff765d;
  --paper: #ffffff;
}

.swim-pass {
  width: 440px;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 16px;
  color: var(--ink);
}

.pass-header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.pass-mark {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  background: var(--water);
  border-radius: 50%;
  font-size: 24px;
}

.pass-title p {
  margin: 0 0 2px;
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
}

.pass-title h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1.1;
}

.lane-details {
  display: flex;
  justify-content: space-between;
  margin: 14px 0;
  padding: 10px 12px;
  background: var(--water);
  border-radius: 8px;
  font-size: 13px;
}

.pass-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.status {
  color: var(--coral);
  font-size: 12px;
  font-weight: 700;
}

.pass-footer button {
  padding: 7px 11px;
  background: var(--blue);
  border: 0;
  border-radius: 6px;
  color: var(--paper);
  font-weight: 700;
}
